-- Vínculo sitio → miembro del CRM por nombre (sin ids a fuego). "Cronos" en el CRM = sitio kronos. TODO(sergi): confirmar.
select s.site_id, m.id from public.members m
join (values ('diamond','diamond'), ('donpool','donpool'), ('mapache','mapache'), ('kronos','kronos'), ('kronos','cronos')) as s(site_id, norm)
  on lower(regexp_replace(m.name, '\s+', '', 'g')) = s.norm
on conflict do nothing;
